import { Router } from "express";
import { z } from "zod";
import { run, toJSON, transaction } from "../db/index.js";
import { notFound } from "../lib/errors.js";
import { newId } from "../lib/ids.js";
import { getChallenges } from "../lib/library.js";
import { assertMovie } from "../lib/movies.js";
import { challenge } from "../lib/schemas.js";
import { validate } from "../middleware/validate.js";

// Mounted at /api/me/challenges — the app's challengeStore. Challenges are
// generated by the app; the server keeps the accepted one and the history.
// Completion happens automatically when the target is marked watched
// (POST /api/me/watched).
const router = Router();

router.get("/", (req, res) => {
  res.json(getChallenges(req.userId));
});

// Accept a challenge. Replaces any active one without counting it as skipped,
// same as the app's acceptChallenge.
router.post("/active", validate(z.object({ challenge })), (req, res) => {
  const accepted = req.body.challenge;
  assertMovie(accepted.targetMovieId);
  transaction(() => {
    run("DELETE FROM challenges WHERE user_id = ? AND status = 'active'", [req.userId]);
    run(
      `INSERT INTO challenges (id, user_id, status, target_movie_id, data, accepted_at)
       VALUES (?, ?, 'active', ?, ?, ?)`,
      [newId("c"), req.userId, accepted.targetMovieId, toJSON(accepted), Date.now()],
    );
  });
  res.status(201).json(getChallenges(req.userId));
});

router.post("/active/skip", (req, res) => {
  const { changes } = run(
    `UPDATE challenges SET status = 'skipped', resolved_at = ?
     WHERE user_id = ? AND status = 'active'`,
    [Date.now(), req.userId],
  );
  if (!changes) throw notFound("No active challenge");
  res.json(getChallenges(req.userId));
});

router.delete("/history", (req, res) => {
  run("DELETE FROM challenges WHERE user_id = ? AND status <> 'active'", [req.userId]);
  res.status(204).end();
});

export default router;
